db.customers.aggregate([
  { $lookup: { from: "orders",
      localField: "_id",
      foreignField: "customer",
      as: "o" } },
  { $project: {
      orders: { $size: "$o" },
      spent: { $sum: "$o.total" } } },
  { $sort: { _id: 1 } }
])

db.customers.aggregate([
  { $match: { _id: "c3" } },
  { $lookup: { from: "orders",
      localField: "_id",
      foreignField: "customer",
      pipeline: [
        { $sort: { _id: 1 } },
        { $project: { status: 1 } }
      ],
      as: "orders" } },
  { $project: { orders: 1 } }
])

db.products.aggregate([
  { $lookup: { from: "orders",
      localField: "_id",
      foreignField: "items.product",
      as: "o" } },
  { $project: { buyers: { $size: {
      $setUnion: ["$o.customer"] } } } },
  { $sort: { _id: 1 } }
])

db.customers.aggregate([
  { $lookup: { from: "customers",
      let: { city: "$city", me: "$_id" },
      pipeline: [
        { $match: { $expr: { $and: [
            { $eq: ["$city", "$$city"] },
            { $ne: ["$_id", "$$me"] }
          ] } } },
        { $project: { _id: 1 } }
      ],
      as: "neighbours" } },
  { $project: { neighbours: 1 } },
  { $sort: { _id: 1 } }
])

db.customers.aggregate([
  { $match: { city: "Accra" } },
  { $sort: { _id: 1 } },
  { $lookup: { from: "products",
      pipeline: [
        { $match: { price: { $gt: 20 } } },
        { $sort: { _id: 1 } },
        { $project: { _id: 1 } }
      ],
      as: "with" } },
  { $project: { with: 1 } }
])

db.customers.aggregate([
  { $match: { _id: "c1" } },
  { $graphLookup: {
      from: "customers",
      startWith: "$_id",
      connectFromField: "_id",
      connectToField: "referrer",
      as: "down",
      depthField: "depth" } },
  { $project: {
      below: { $size: "$down" },
      deepest: { $add: [
        { $max: "$down.depth" }, 1] } } }
])

